test("@smoke projects list", async ({ page }) => {
  await page.goto("/projects");
  await waitForHydration(page);
  // Signed out: the proposal door stays hidden, like the bookmarks count.
  await expect(page.getByRole("link", { name: "Propose project" })).toHaveCount(
    0
  );
  // The sign-in prompt under the search is a link inside muted prose (#361).
  await expectUnderlinedAtRest(
    page.getByRole("link", { name: "Sign in to get recommendations" })
  );
  // The fields and the syntax are on the hint line under the row, and the
  // searchbox is described by it; the placeholder is only a name (#369).
  await expect(
    page.getByRole("searchbox", { name: "Search projects" })
  ).toHaveAccessibleDescription(/Quote a "phrase"/);
  await checkA11y(page);
});

test("@smoke projects list, paginated", async ({ page }) => {
  await page.goto("/projects");
  await waitForHydration(page);

  const pager = page.getByRole("navigation", { name: "Pagination" });
  await expect(pager).toBeVisible();

  // The seeded catalog fits on one page, so both controls are disabled here.
  // pointer-events-none used to leave a disabled control focusable and
  // activatable, which no axe rule reports: it must be out of the tab order
  // entirely, not just unclickable with a mouse.
  for (const label of ["Previous", "Next"]) {
    const control = pager.getByText(label);
    await expect(control).toHaveAttribute("aria-disabled", "true");
    await expect(control).toHaveAttribute("tabindex", "-1");
  }
  await checkA11y(page);
});

test("@smoke projects list, filters aside at xl", async ({ page }) => {
  // The suite runs at 1280, which is where the aside appears (#350): the
  // program select and the switches are in it, and the Filters button that
  // opens the sheet is gone.
  await page.goto("/projects");
  await waitForHydration(page);
  const aside = page.getByRole("complementary", { name: "Filters" });
  await expect(aside.getByRole("combobox", { name: "Program" })).toBeVisible();
  // The archive mode is a radio above the switches, and the accepting
  // switch carries its hint as its description (#383). That switch is the
  // one that opens on (#419), so its hint says what turning it off does.
  await expect(aside.getByRole("radiogroup", { name: "Show" })).toBeVisible();
  await expect(
    aside.getByRole("radio", { name: "Current projects" })
  ).toBeChecked();
  const archived = aside.getByRole("radio", { name: "Archived projects" });
  await expect(archived).toBeVisible();
  const accepting = aside.getByRole("switch", {
    name: "are looking for team members",
  });
  await expect(accepting).toBeVisible();
  await expect(accepting).toBeChecked();
  await expect(accepting).toHaveAccessibleDescription(
    "Turn off to also show projects whose team is full."
  );
  await expect(page.getByRole("button", { name: "Filters" })).toBeHidden();
  await checkA11y(page);
  // Picking Archived lands on the same param a pasted link carries.
  await archived.click();
  await expect(page).toHaveURL(/archivedOnly=true/);
  await expect(archived).toBeChecked();
  await expect(
    aside.getByRole("radio", { name: "Current projects" })
  ).not.toBeChecked();
});

test("@smoke projects list, filters sheet at 375px", async ({ page }) => {
  // Below xl the same form opens in a left sheet; a change made there keeps
  // the sheet open, since it is a navigation on the same route.
  await page.setViewportSize({ width: 375, height: 812 });
  await page.goto("/projects");
  await waitForHydration(page);
  await expect(
    page.getByRole("complementary", { name: "Filters" })
  ).toBeHidden();
  await page.getByRole("button", { name: "Filters" }).click();
  const sheet = page.getByRole("dialog", { name: "Filters" });
  const accepting = sheet.getByRole("switch", {
    name: "are looking for team members",
  });
  await expect(accepting).toBeVisible();
  // Focus lands inside the sheet on open, and the page under it does not
  // grow sideways for the overlay.
  await expect(sheet.locator(":focus")).toHaveCount(1);
  await expectNoHorizontalOverflow(page);
  await checkA11y(page);
  // Off, not on: this switch opens checked (#419), so the click that moves it
  // away from its default is the one the Filters badge counts below.
  await accepting.click();
  await expect(page).toHaveURL(/acceptingOnly=false/);
  await expect(sheet).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(sheet).toBeHidden();
  // Focus returns to the button, which now carries the count of what was
  // changed. Tab from the search reaches it with nothing in between: the
  // recommendation prompt renders under the row, not inside it. Four
  // stops: the sort, the two view toggle buttons, the Filters button.
  const button = page.getByRole("button", { name: "Filters 1" });
  await expect(button).toBeFocused();
  await page.getByRole("searchbox", { name: "Search projects" }).focus();
  for (let i = 0; i < 4; i += 1) {
    await page.keyboard.press("Tab");
  }
  await expect(button).toBeFocused();
  // Enter opens it from the keyboard, and Clear all (a link-variant Button,
  // visible now that a filter is on) is what the dark scan measures.
  await page.keyboard.press("Enter");
  await expect(sheet).toBeVisible();
  await expect(sheet.getByRole("button", { name: "Clear all" })).toBeVisible();
  await checkA11y(page);
  await page.keyboard.press("Escape");
  await expect(sheet).toBeHidden();
});

